int search(List<int> a, int t, [int lo = 0, int? hi]) {
  hi ??= a.length - 1;
  if (lo > hi) return -1;
  final mid = (lo + hi) ~/ 2;
  if (a[mid] == t) return mid;
  return a[mid] < t ? search(a, t, mid + 1, hi) : search(a, t, lo, mid - 1);
}

void main() {
  print(search([1, 4, 9, 16, 25], 16));
}
```

