void perms(List<String> items, List<String> cur, Set<int> used, List<String> out) {
  if (cur.length == items.length) {
    out.add(cur.join());
    return;
  }
  for (var i = 0; i < items.length; i++) {
    if (used.contains(i)) continue;
    used.add(i);
    cur.add(items[i]);
    perms(items, cur, used, out);
    cur.removeLast();
    used.remove(i);
  }
}

void main() {
  final out = <String>[];
  perms(['x', 'y'], [], {}, out);
  print(out);
}
```

